import { AmountType } from "./amountType";

// Dates are ISO `yyyy-MM-dd` strings (server `DateOnly`); parse them with
// `parseIsoDate` from `formatting/format.ts` to avoid timezone shifts.
export interface Bill {
  id: number;
  // Null for one-off bills; set when the bill was generated by a RecurringBill.
  recurringBillId: number | null;
  name: string;
  dueDate: string;
  amountType: AmountType;
  value: number | null;
  // Average of the last 3 paid values; only for VariableEstimated bills.
  estimate: number | null;
  paidAt: string | null;
}

export interface NewBill {
  name: string;
  dueDate: string;
  amountType: AmountType;
  value?: number | null;
}

export interface BillPayment {
  // Required for variable bills; optional for Fixed (overrides the value).
  value?: number | null;
}
